package edu.smartlibrary.service;

import edu.smartlibrary.api.ApiModels.*;import edu.smartlibrary.model.*;import edu.smartlibrary.repo.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;import java.time.*;import java.util.*;import java.util.stream.*;

@Service public class LibraryService {
 private final UserRepository users;private final BookRepository books;private final LoanRepository loans;
 @Value("${app.library.loan-days}") private int loanDays;@Value("${app.library.borrow-limit}") private int borrowLimit;@Value("${app.library.fine-per-day}") private BigDecimal finePerDay;
 public LibraryService(UserRepository u,BookRepository b,LoanRepository l){users=u;books=b;loans=l;}
 public UserView userView(AppUser u){return new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole().name().toLowerCase(Locale.ROOT));}
 public Map<String,Object> libraryRules(){return Map.of("loanDays",loanDays,"borrowLimit",borrowLimit,"finePerDay",finePerDay);}
 public BookView bookView(Book b){return new BookView(b.getId(),b.getTitle(),b.getAuthor(),b.getCategory(),b.getIsbn(),b.getPublisher(),b.getPublicationYear(),b.getDescription(),b.getTotalCopies(),b.getAvailableCopies(),b.getShelfLocation(),b.getCreatedAt(),b.getUpdatedAt());}
 public Page<BookView> searchBooks(String q,String category,int page,int size){if(page<0||size<1||size>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Page must be nonnegative and size must be between 1 and 100.");String term=q==null||q.isBlank()?null:q.trim();String cat=category==null||category.isBlank()||category.equalsIgnoreCase("all")?null:category.trim();return books.search(term,cat,PageRequest.of(page,size,Sort.by("title").ascending())).map(this::bookView);}
 public BookView createBook(BookRequest r){String isbn=blank(r.isbn());if(isbn!=null&&books.existsByIsbnIgnoreCase(isbn))throw new ResponseStatusException(HttpStatus.CONFLICT,"That ISBN is already assigned to another book.");return bookView(books.save(new Book(r.title().trim(),r.author().trim(),r.category().trim(),isbn,blank(r.publisher()),r.publicationYear(),blank(r.description()),r.totalCopies(),blank(r.shelfLocation()))));}
 @Transactional public BookView updateBook(Long id,BookRequest r){Book b=books.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found."));if(r.isbn()!=null&&!r.isbn().isBlank()&&books.existsByIsbnIgnoreCaseAndIdNot(r.isbn().trim(),id))throw new ResponseStatusException(HttpStatus.CONFLICT,"That ISBN is already assigned to another book.");try{b.update(r.title().trim(),r.author().trim(),r.category().trim(),blank(r.isbn()),blank(r.publisher()),r.publicationYear(),blank(r.description()),r.totalCopies(),blank(r.shelfLocation()));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}return bookView(b);}
 @Transactional public void deleteBook(Long id){Book b=books.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found."));if(b.getAvailableCopies()<b.getTotalCopies())throw new ResponseStatusException(HttpStatus.CONFLICT,"This book has active loans and cannot be deleted.");if(loans.existsByBook_Id(id))throw new ResponseStatusException(HttpStatus.CONFLICT,"This book has borrowing history and cannot be deleted.");books.delete(b);}
 private String blank(String v){return v==null||v.isBlank()?null:v.trim();}
 @Transactional public LoanView issue(AppUser requester,boolean librarian,LoanRequest req){if(librarian&&req.studentId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Select a student to issue this book to.");AppUser borrower=users.lockById(librarian?req.studentId():requester.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student account not found."));if(borrower.getRole()!=Role.STUDENT)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Books can only be issued to student accounts.");if(loans.countByBorrowerAndStatus(borrower,"ISSUED")>=borrowLimit)throw new ResponseStatusException(HttpStatus.CONFLICT,"Borrowing limit reached ("+borrowLimit+" active books).");Book book=books.lockById(req.bookId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found."));if(loans.countActiveForBook(borrower,book.getId())>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This student already has an active loan for this book.");try{book.issueOne();}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}LocalDate today=LocalDate.now();return loanView(loans.save(new Loan(borrower,book,today,today.plusDays(loanDays))));}
 @Transactional public LoanView returnLoan(AppUser requester,boolean librarian,Long id){Loan loan=loans.lockById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Borrowing record not found."));if(!librarian&&!loan.getBorrower().getId().equals(requester.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only return books issued to your account.");if(!"ISSUED".equals(loan.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This book has already been returned.");Book book=books.lockById(loan.getBook().getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Book not found."));LocalDate today=LocalDate.now();long days=Math.max(0,Duration.between(loan.getDueDate().atStartOfDay(),today.atStartOfDay()).toDays());book.returnOne();loan.close(today,finePerDay.multiply(BigDecimal.valueOf(days)));return loanView(loan);}
 @Transactional(readOnly=true) public List<LoanView> transactions(AppUser requester,boolean librarian){return (librarian?loans.findAllByOrderByIssueDateDesc():loans.findByBorrowerOrderByIssueDateDesc(requester)).stream().map(this::loanView).toList();}
 public LoanView loanView(Loan l){long late="ISSUED".equals(l.getStatus())?Math.max(0,Duration.between(l.getDueDate().atStartOfDay(),LocalDate.now().atStartOfDay()).toDays()):0;return new LoanView(l.getId(),l.getBook().getId(),l.getBook().getTitle(),l.getBook().getAuthor(),l.getBorrower().getId(),l.getBorrower().getName(),l.getBorrower().getEmail(),l.getIssueDate(),l.getDueDate(),l.getReturnDate(),l.getFine(),l.getStatus().toLowerCase(Locale.ROOT),late,finePerDay.multiply(BigDecimal.valueOf(late)));}
 @Transactional(readOnly=true) public List<Recommendation> recommendations(AppUser user){List<Object[]> prefs=loans.preferredCategories(user);String fav=prefs.isEmpty()?null:(String)prefs.get(0)[0];List<Object[]> popular=loans.popularBookIds();Map<Long,Long> counts=popular.stream().collect(Collectors.toMap(x->((Number)x[0]).longValue(),x->((Number)x[1]).longValue()));Set<Long> borrowedOften=loans.findByBorrowerOrderByIssueDateDesc(user).stream().collect(Collectors.groupingBy(x->x.getBook().getId(),Collectors.counting())).entrySet().stream().filter(e->e.getValue()>=2).map(Map.Entry::getKey).collect(Collectors.toSet());List<Book> candidates=books.findAll().stream().filter(b->b.getAvailableCopies()>0&&!borrowedOften.contains(b.getId())).toList();return candidates.stream().sorted(Comparator.<Book>comparingInt(b->fav!=null&&fav.equalsIgnoreCase(b.getCategory())?1:0).reversed().thenComparing((Book b)->counts.getOrDefault(b.getId(),0L),Comparator.reverseOrder()).thenComparing(Book::getTitle)).limit(8).map(b->new Recommendation(bookView(b),fav!=null&&fav.equalsIgnoreCase(b.getCategory())?"Recommended because you often borrow "+fav+" books.":prefs.isEmpty()?"A popular available title to start your reading journey.":"Popular with library readers and currently available.",counts.getOrDefault(b.getId(),0L))).toList();}
 @Transactional(readOnly=true) public Map<String,Object> dashboard(AppUser u,boolean librarian){Map<String,Object> d=new LinkedHashMap<>();if(librarian){d.put("totalBooks",books.findAll().stream().mapToInt(Book::getTotalCopies).sum());d.put("availableBooks",books.findAll().stream().mapToInt(Book::getAvailableCopies).sum());d.put("borrowedBooks",loans.countByStatus("ISSUED"));d.put("registeredStudents",users.countByRole(Role.STUDENT));d.put("overdueBooks",loans.countByStatusAndDueDateBefore("ISSUED",LocalDate.now()));d.put("outstandingFines",loans.findAll().stream().filter(l->"ISSUED".equals(l.getStatus())&&l.getDueDate().isBefore(LocalDate.now())).map(l->finePerDay.multiply(BigDecimal.valueOf(Duration.between(l.getDueDate().atStartOfDay(),LocalDate.now().atStartOfDay()).toDays()))).reduce(BigDecimal.ZERO,BigDecimal::add));d.put("categories",books.categoryStats().stream().map(x->Map.of("name",x[0],"count",x[1])).toList());d.put("popularBooks",popular());d.put("recentActivity",loans.findAllByOrderByIssueDateDesc().stream().limit(6).map(this::loanView).toList());}else{d.put("currentlyBorrowed",loans.countByBorrowerAndStatus(u,"ISSUED"));d.put("overdueBooks",loans.findByBorrowerOrderByIssueDateDesc(u).stream().filter(l->"ISSUED".equals(l.getStatus())&&l.getDueDate().isBefore(LocalDate.now())).count());d.put("outstandingFines",loans.findByBorrowerOrderByIssueDateDesc(u).stream().map(this::loanView).map(LoanView::currentFine).reduce(BigDecimal.ZERO,BigDecimal::add));d.put("recentActivity",loans.findByBorrowerOrderByIssueDateDesc(u).stream().limit(5).map(this::loanView).toList());d.put("recommendations",recommendations(u));}return d;}
 private List<BookView> popular(){return loans.popularBookIds().stream().limit(5).map(o->books.findById(((Number)o[0]).longValue()).orElse(null)).filter(Objects::nonNull).map(this::bookView).toList();}
 @Transactional(readOnly=true) public List<Map<String,Object>> members(){return users.findAll().stream().filter(u->u.getRole()==Role.STUDENT).map(u->{List<Loan> ls=loans.findByBorrowerOrderByIssueDateDesc(u);return Map.<String,Object>of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role","student","totalBorrowings",ls.size(),"currentlyBorrowed",ls.stream().filter(l->"ISSUED".equals(l.getStatus())).count());}).toList();}
 public UserView createMember(String name,String email,String password,org.springframework.security.crypto.password.PasswordEncoder encoder){if(users.existsByEmailIgnoreCase(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account already uses this email.");return userView(users.save(new AppUser(name.trim(),email.trim().toLowerCase(Locale.ROOT),encoder.encode(password),Role.STUDENT)));}
}
